# Reference values from OrdinaryDiffEqFIRK, OrdinaryDiffEqPDIRK,
# OrdinaryDiffEqQPRK and OrdinaryDiffEqPRK, generated by tools/firk-probe.jl:
# saved points, f evaluations, Jacobians, W factorizations, linear solves,
# rejections, accepted steps and the final state.

firkt_lv <- function(u, p, t) c(p[1] * u[1] - u[1] * u[2], -p[2] * u[2] + u[1] * u[2])
firkt_lvprob <- ODEProblem(firkt_lv, c(1, 1), c(0, 2), c(1.5, 3))
firkt_n <- 8
firkt_heat <- function(u, p, t) {
  l <- c(0, u[-firkt_n]); r <- c(u[-1], 0)
  p[1] * (l - 2 * u + r) * (firkt_n + 1)^2 - 0.5 * (u * u * u) + 0.1 * t
}
firkt_heatjac <- function(u, p, t) {
  J <- matrix(0, firkt_n, firkt_n)
  for (i in seq_len(firkt_n)) {
    J[i, i] <- -2 * p[1] * (firkt_n + 1)^2 - 1.5 * u[i]^2
    if (i > 1) J[i, i - 1] <- p[1] * (firkt_n + 1)^2
    if (i < firkt_n) J[i, i + 1] <- p[1] * (firkt_n + 1)^2
  }
  J
}
firkt_heatprob <- ODEProblem(ODEFunction(firkt_heat, jac_fn = firkt_heatjac),
                             seq_len(firkt_n) * (firkt_n + 1 - seq_len(firkt_n)) / firkt_n^2, c(0, 0.3), 1)
firkt_vdp <- function(u, p, t) c(u[2], p[1] * ((1 - u[1] * u[1]) * u[2]) - u[1])
firkt_vdpjac <- function(u, p, t) matrix(c(0, -2 * p[1] * u[1] * u[2] - 1, 1, p[1] * (1 - u[1] * u[1])), 2, 2)
firkt_vdpprob <- ODEProblem(ODEFunction(firkt_vdp, jac_fn = firkt_vdpjac), c(2, 0), c(0, 6), 10)
firkt_rober <- function(u, p, t) {
  c(-p[1] * u[1] + p[2] * u[2] * u[3], p[1] * u[1] - p[2] * u[2] * u[3] - p[3] * (u[2] * u[2]), u[1] + u[2] + u[3] - 1)
}
firkt_roberjac <- function(u, p, t) {
  rbind(c(-p[1], p[2] * u[3], p[2] * u[2]), c(p[1], -p[2] * u[3] - 2 * p[3] * u[2], -p[2] * u[2]), c(1, 1, 1))
}
firkt_roberprob <- ODEProblem(ODEFunction(firkt_rober, mass_matrix = diag(c(1, 1, 0)), jac_fn = firkt_roberjac),
                              c(1, 0, 0), c(0, 10), c(0.04, 1e4, 3e7))
firkt_cbheat <- function() DiscreteCallback(function(u, t, integ) t == 0.1, function(integ) integ$u <- integ$u * 0.5)
firkt_cblv <- function() DiscreteCallback(function(u, t, integ) t == 1, function(integ) integ$u <- integ$u * 0.5)

firkt_check <- function(sol, stats, u) {
  st <- sol$stats
  expect_identical(c(length(sol$t), st$nf, st$njacs, st$nw, st$nsolve, st$nreject, st$naccept), as.integer(stats))
  expect_equal(sol$u[[length(sol$u)]], u, tolerance = 1e-10)
}

# final heat states, symmetric up to rounding
firkt_sym <- function(...) {
  h <- c(...)
  c(h, rev(h))
}

test_that("the generated FIRK tableaus reproduce the tableaus Julia caches", {
  ns <- asNamespace("modelcompR")
  gen <- function(fn) {
    f <- get(fn, ns)
    environment(f) <- list2env(list(.FIRK_TAB = list()), parent = ns)
    f
  }
  rt <- gen(".firk_radau_tab"); gt <- gen(".firk_gauss_tab")
  # the eigenvectors of the seven stage matrix are ill conditioned
  for (s in c(3L, 5L, 7L)) {
    a <- rt(s); b <- ns$.FIRK_TAB[[paste0("Radau", s)]]
    for (k in names(b)) expect_equal(a[[k]], b[[k]], tolerance = if (s == 7L) 1e-9 else 1e-12, info = paste(s, k))
  }
  for (s in 2:5) {
    a <- gt(s); b <- ns$.FIRK_TAB[[paste0("Gauss", s)]]
    for (k in names(b)) expect_equal(a[[k]], b[[k]], tolerance = 1e-13, info = paste(s, k))
  }
  # GaussLegendreTableau(Float64, Float64, 6), built by Julia at run time
  g6 <- gt(6L)
  expect_equal(g6$c, c(0.033765242898423975, 0.16939530676686776, 0.38069040695840156, 0.6193095930415985,
                       0.8306046932331322, 0.966234757101576), tolerance = 1e-15)
  expect_equal(g6$b, c(0.08566224618958512, 0.18038078652406925, 0.23395696728634563, 0.23395696728634563,
                       0.18038078652406925, 0.08566224618958512), tolerance = 1e-14)
  expect_equal(g6$e, c(-8.14126172900853, 24.533738740695192, -36.16834049547177, 36.168340495471895,
                       -24.533738740695437, 8.141261729008647), tolerance = 1e-12)
  expect_equal(g6$A[1:2, 1:3], matrix(c(0.04283112309479256, 0.09267349143037885, -0.014763725997197401,
                                        0.09019039326203471, 0.009325050706477746, -0.020300102293239627), 2, 3),
               tolerance = 1e-13)
})

test_that("KuttaPRK2p5 and QPRK98 match OrdinaryDiffEq", {
  firkt_check(solve(firkt_lvprob, KuttaPRK2p5(), dt = 0.05), c(41, 0, 0, 0, 0, 0, 40),
              c(6.777189840304527, 2.0127536968756545))
  firkt_check(solve(firkt_lvprob, KuttaPRK2p5(), dt = 0.05, tstops = 1, callback = firkt_cblv()),
              c(42, 1, 0, 0, 0, 0, 40), c(5.653932511282807, 0.1342327602847254))
  firkt_check(solve(firkt_lvprob, QPRK98(), reltol = 1e-8, abstol = 1e-10), c(19, 291, 0, 0, 0, 0, 18),
              c(6.77718932703933, 2.012753752404957))
  firkt_check(solve(firkt_lvprob, QPRK98(), reltol = 1e-8, abstol = 1e-10, tstops = 1), c(21, 323, 0, 0, 0, 0, 20),
              c(6.7771892937598714, 2.0127537741694894))
  firkt_check(solve(firkt_lvprob, QPRK98(), reltol = 1e-8, abstol = 1e-10, tstops = 1, callback = firkt_cblv()),
              c(21, 308, 0, 0, 0, 0, 19), c(5.6539325838089125, 0.1342327506099471))
  firkt_check(solve(firkt_lvprob, QPRK98(), dt = 0.25, adaptive = FALSE), c(9, 129, 0, 0, 0, 0, 8),
              c(6.777179901694695, 2.012762890599137))
})

test_that("PDIRK44 matches OrdinaryDiffEqPDIRK", {
  heat <- firkt_sym(0.006993885662417061, 0.012958325915643786, 0.017305865284348146, 0.019597038095240316)
  firkt_check(solve(firkt_heatprob, PDIRK44(), dt = 0.01), c(31, 240, 120, 120, 240, 0, 30), heat)
  firkt_check(solve(firkt_heatprob, PDIRK44(threading = FALSE), dt = 0.01), c(31, 240, 120, 120, 240, 0, 30), heat)
  firkt_check(solve(firkt_heatprob, PDIRK44(), dt = 0.01, tstops = 0.1, callback = firkt_cbheat()),
              c(32, 240, 120, 120, 240, 0, 30),
              firkt_sym(0.004010445341616208, 0.007351303287359805, 0.00975156093384249, 0.011006612533710354))
})

test_that("RadauIIA3, RadauIIA5 and RadauIIA9 match OrdinaryDiffEqFIRK", {
  tol <- function(A, ...) solve(firkt_heatprob, A, reltol = 1e-4, abstol = 1e-6, ...)
  firkt_check(tol(RadauIIA3(), tstops = 0.1, callback = firkt_cbheat()), c(123, 276, 122, 122, 136, 1, 121),
              firkt_sym(0.004010462424590841, 0.0073513353921164475, 0.009751604187341903, 0.01100666171894314))
  firkt_check(solve(firkt_vdpprob, RadauIIA3(), dt = 0.05, adaptive = FALSE), c(121, 253, 120, 120, 126, 0, 120),
              c(1.4925180879289601, -0.11963652223746386))

  firkt_check(tol(RadauIIA5()), c(13, 74, 13, 13, 52, 1, 12),
              firkt_sym(0.0069939518893108316, 0.012958450288119282, 0.0173060327079818, 0.019597228376328234))
  firkt_check(tol(RadauIIA5(), tstops = 0.1), c(14, 81, 14, 14, 57, 1, 13),
              firkt_sym(0.00699394862699884, 0.012958444205791172, 0.01730602458806701, 0.019597219198199407))
  firkt_check(tol(RadauIIA5(), tstops = 0.1, callback = firkt_cbheat()), c(15, 80, 14, 14, 56, 1, 13),
              firkt_sym(0.004010479433553759, 0.007351367350625619, 0.009751647228913505, 0.011006710652693433))
  firkt_check(solve(firkt_vdpprob, RadauIIA5(), reltol = 1e-6, abstol = 1e-8), c(31, 269, 32, 32, 188, 2, 30),
              c(1.4925182338569025, -0.1196366278496202))
  firkt_check(solve(firkt_vdpprob, RadauIIA5(), dt = 0.05, adaptive = FALSE), c(121, 493, 120, 120, 248, 0, 120),
              c(1.4925182139138844, -0.11963647634342661))

  firkt_check(tol(RadauIIA9()), c(7, 71, 7, 7, 44, 1, 6),
              firkt_sym(0.006993923477403706, 0.012958396083655403, 0.017305958648440433, 0.01959714352832561))
  firkt_check(tol(RadauIIA9(), tstops = 0.1), c(7, 76, 7, 7, 47, 1, 6),
              firkt_sym(0.006993924946974955, 0.012958399704565787, 0.017305964636404665, 0.019597151027829114))
  firkt_check(tol(RadauIIA9(), tstops = 0.1, callback = firkt_cbheat()), c(8, 78, 7, 7, 48, 1, 6),
              firkt_sym(0.004010462401506867, 0.007351342015628008, 0.00975161108387518, 0.011006668531602183))
  firkt_check(solve(firkt_vdpprob, RadauIIA9(), reltol = 1e-6, abstol = 1e-8), c(14, 231, 15, 15, 142, 0, 13),
              c(1.492518238897247, -0.11963652306872294))
})

test_that("RadauIIA5 options and mass matrices match OrdinaryDiffEqFIRK", {
  firkt_check(solve(firkt_heatprob, RadauIIA5(extrapolant = "constant"), reltol = 1e-4, abstol = 1e-6),
              c(13, 92, 13, 13, 64, 1, 12),
              firkt_sym(0.006993954220150363, 0.012958454744643546, 0.017306038828566416, 0.01959723542269453))
  firkt_check(solve(firkt_vdpprob, RadauIIA5(kappa = 0.1, smooth_est = FALSE), reltol = 1e-6, abstol = 1e-8),
              c(143, 648, 146, 146, 332, 4, 142), c(1.4925182601616527, -0.11963647059203172))
  # the consistency check of the initial values evaluates f once more in R
  # than in CheckInit, which does not count it
  firkt_check(solve(firkt_roberprob, RadauIIA5(), reltol = 1e-6, abstol = 1e-8, initializealg = NoInit()),
              c(25, 190, 27, 27, 133, 1, 24), c(0.8413699447580493, 1.623390969486044e-5, 0.15861382133225596))
  # with the default initial step the first error estimate of RadauIIA9 here
  # is rounding (about 1e-18), so the step sizes part from the second step on
  firkt_check(solve(firkt_roberprob, RadauIIA9(), dt = 5e-4, reltol = 1e-6, abstol = 1e-8, initializealg = NoInit()),
              c(14, 249, 15, 15, 154, 0, 13), c(0.8413700225436946, 1.6233862259167287e-5, 0.1586137435940461))
})

test_that("the dense output matches OrdinaryDiffEq between the steps", {
  dense <- function(sol, t, u) expect_equal(as.numeric(sol(t)), u, tolerance = 1e-12)
  heat <- function(A) solve(firkt_heatprob, A, reltol = 1e-4, abstol = 1e-6)
  vdp <- function(A) solve(firkt_vdpprob, A, reltol = 1e-6, abstol = 1e-8)
  dense(vdp(RadauIIA3()), 5.55, c(1.5441425010363252, -0.11020920637742475))
  r5 <- c(0.033676541561306596, 0.06321606719640444, 0.08510872995790565, 0.09674835318515781,
          0.0967483531851578, 0.08510872995790565, 0.06321606719640445, 0.0336765415613066)
  dense(heat(RadauIIA5()), 0.1234, r5)
  dense(vdp(RadauIIA9()), 2.5, c(1.8226971414152826, -0.07822358768678099))
  dense(heat(GaussLegendre(num_stages = 3)), 0.2718,
        c(0.008748308786326016, 0.016273566929550707, 0.02178746385024602, 0.02470146952802964,
          0.02470146952802964, 0.02178746385024602, 0.016273566929550707, 0.008748308786326018))
  dense(vdp(AdaptiveRadau()), 2.5, c(1.8226971289485263, -0.07822359016632435))
  dense(solve(firkt_heatprob, PDIRK44(), dt = 0.01), 0.1234,
        c(0.03367731145457546, 0.06321748403359326, 0.08511059229835109, 0.0967504360864673,
          0.09675043608646727, 0.08511059229835108, 0.06321748403359324, 0.03367731145457544))
  dense(solve(firkt_lvprob, QPRK98(), reltol = 1e-8, abstol = 1e-10), 1.23, c(3.6876301318353417, 0.27144705345043013))
  dense(solve(firkt_lvprob, KuttaPRK2p5(), dt = 0.05), 0.37, c(1.3365581836795013, 0.5030060822742787))
  # Julia's dense output differs here: with extrapolant = :constant it keeps
  # the stage values at zero (the state of the step start), and AdaptiveRadau
  # interpolates every step with the stage count in force at the end (five
  # stages, where this step took three); here both use the stages of the
  # step. With three stages AdaptiveRadau is RadauIIA5.
  s <- heat(RadauIIA5(extrapolant = "constant"))
  expect_equal(as.numeric(s(0.1234)), r5, tolerance = 1e-4)
  s <- heat(AdaptiveRadau())
  expect_equal(as.numeric(s(0.1234)), r5, tolerance = 1e-12)
})

test_that("GaussLegendre matches OrdinaryDiffEqFIRK", {
  tol <- function(s, ...) solve(firkt_heatprob, GaussLegendre(num_stages = s), reltol = 1e-4, abstol = 1e-6, ...)
  firkt_check(tol(3), c(71, 620, 77, 77, 103, 7, 70),
              firkt_sym(0.006993924832903344, 0.01295839952588119, 0.01730596444966754, 0.019597150854845088))
  firkt_check(tol(3, tstops = 0.1, callback = firkt_cbheat()), c(71, 611, 76, 76, 101, 7, 69),
              firkt_sym(0.0040104649436284515, 0.007351340126425406, 0.009751610565960312, 0.011006668972514974))
  firkt_check(tol(5), c(26, 460, 32, 32, 53, 7, 25),
              firkt_sym(0.006993924963406161, 0.012958399906586142, 0.01730596516774976, 0.019597151822819934))
  firkt_check(tol(5, tstops = 0.1, callback = firkt_cbheat()), c(33, 522, 38, 38, 58, 7, 31),
              firkt_sym(0.004010464972365295, 0.0073513401959560834, 0.009751610683104631, 0.011006669123021513))
  firkt_check(solve(firkt_vdpprob, GaussLegendre(num_stages = 3), reltol = 1e-6, abstol = 1e-8),
              c(225, 1950, 231, 231, 341, 7, 224), c(1.4925182336318665, -0.11963647318501756))
  firkt_check(solve(firkt_vdpprob, GaussLegendre(num_stages = 5), reltol = 1e-6, abstol = 1e-8),
              c(68, 1110, 67, 67, 141, 0, 67), c(1.4925182337323668, -0.11963647477272413))
  # six stages: the tableau is built at run time
  firkt_check(solve(firkt_vdpprob, GaussLegendre(num_stages = 6), reltol = 1e-8, abstol = 1e-10),
              c(72, 1508, 71, 71, 168, 0, 71), c(1.4925182335891085, -0.11963647252757255))
  firkt_check(solve(firkt_vdpprob, GaussLegendre(num_stages = 1), dt = 0.05, adaptive = FALSE),
              c(121, 400, 120, 120, 159, 0, 120), c(1.4925182096809368, -0.11963353403224507))
  firkt_check(solve(firkt_vdpprob, GaussLegendre(num_stages = 3), dt = 0.05, adaptive = FALSE),
              c(121, 916, 120, 120, 145, 0, 120), c(1.4925182358373899, -0.11963650149349869))
})

