  firkt_check(solve(firkt_heatprob, AdaptiveRadau(), reltol = 1e-4, abstol = 1e-6, tstops = 0.1,
                    callback = firkt_cbheat()), c(14, 97, 14, 14, 65, 1, 12),
              c(0.004010465786250576, 0.007351341428502349, 0.009751612044863314, 0.011006670226347985,
                0.011006670226347957, 0.0097516120448633, 0.007351341428502332, 0.004010465786250559))
  firkt_check(solve(firkt_vdpprob, AdaptiveRadau(), reltol = 1e-6, abstol = 1e-8), c(23, 329, 25, 25, 208, 0, 22),
              c(1.492518233924224, -0.11963647530435317))
  firkt_check(solve(firkt_vdpprob, AdaptiveRadau(), reltol = 1e-10, abstol = 1e-12), c(33, 689, 36, 36, 415, 0, 32),
              c(1.4925182335864124, -0.11963647246685746))
  firkt_check(solve(firkt_vdpprob, AdaptiveRadau(min_order = 9, max_order = 13), reltol = 1e-8, abstol = 1e-10),
              c(19, 494, 23, 23, 292, 0, 18), c(1.492518233587188, -0.11963647246443758))
  firkt_check(solve(firkt_heatprob, AdaptiveRadau(min_order = 5, max_order = 9), reltol = 1e-8, abstol = 1e-10),
              c(20, 170, 20, 20, 112, 1, 19),
              firkt_sym(0.006993924824714892, 0.012958399509489363, 0.017305964426054657, 0.019597150826862184))
  # nine stages: the tableau is built at run time
  firkt_check(solve(firkt_vdpprob, AdaptiveRadau(min_order = 13, max_order = 17), reltol = 1e-10, abstol = 1e-12),
              c(16, 585, 18, 18, 339, 0, 15), c(1.492518233586384, -0.1196364724658899))
})

test_that("the FIRK methods fix two defects of the out of place Julia steps", {
  # Julia's out of place RadauIIA3 skips the Newton convergence check and
  # returns 25/107/27/27/52/3/24 here; the checked step rejects more
  sol <- solve(firkt_roberprob, RadauIIA3(), reltol = 1e-3, abstol = 1e-6, initializealg = NoInit())
  firkt_check(sol, c(27, 113, 32, 32, 55, 4, 26), c(0.84136863891620006, 1.6233807352218329e-05, 0.15861512727644775))
  # and accepts the divergent iterate of a fixed step (u(2) = -5.379872315981146e9)
  cub <- ODEProblem(ODEFunction(function(u, p, t) -p[1] * (u * u * u),
                                jac_fn = function(u, p, t) matrix(-3 * p[1] * (u * u), 1, 1)), 1, c(0, 2), 1000)
  expect_warning(sol <- solve(cub, RadauIIA3(), dt = 0.25, adaptive = FALSE), "nonlinear solver")
  expect_identical(sol$retcode, "ConvergenceFailure")
  # Julia's out of place AdaptiveRadau multiplies the mass matrix across the
  # stages (`mass_matrix * w`) and stops at t = 1.5625e-8; applied to each
  # stage it follows RadauIIA5
  sol <- solve(firkt_roberprob, AdaptiveRadau(), reltol = 1e-6, abstol = 1e-8)
  expect_identical(sol$retcode, "Success")
  expect_equal(sol$u[[length(sol$u)]], c(0.8413699447580493, 1.623390969486044e-5, 0.15861382133225596),
               tolerance = 1e-6)
})

test_that("the FIRK constructors check their arguments", {
  expect_error(AdaptiveRadau(min_order = 3), "below 5")
  expect_error(AdaptiveRadau(min_order = 9, max_order = 5), "below min_order")
  expect_error(GaussLegendre(num_stages = 0), "positive integer")
  expect_error(RadauIIA5(extrapolant = "linear"), "extrapolant")
  expect_equal(alg_order(RadauIIA9()), 9)
})
